source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Full-width/full-height solid lines are the panel dividers.
    hdiv = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    vdiv = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    row_spans = []
    start = 0
    for r in hdiv:
        if start < r:
            row_spans.append((start, r))
        start = r + 1
    if start < h:
        row_spans.append((start, h))
    col_spans = []
    start = 0
    for c in vdiv:
        if start < c:
            col_spans.append((start, c))
        start = c + 1
    if start < w:
        col_spans.append((start, w))

    divider_colors = {grid[r][0] for r in hdiv} | {grid[0][c] for c in vdiv}
    colors = {v for row in grid for v in row if v != 0 and v not in divider_colors}
    # Each motif color belongs to one neighboring panel seam. Infer it from
    # the seam where the input already contains the most mirrored pairs.
    seams = {}
    for color in colors:
        best = None
        for j in range(len(col_spans) - 1):
            l0, l1 = col_spans[j]
            r0, r1 = col_spans[j + 1]
            width = min(l1 - l0, r1 - r0)
            if width == 0:
                continue
            score = 0
            for y0, y1 in row_spans:
                for y in range(y0, y1):
                    for k in range(width):
                        if grid[y][l0+k] == color and grid[y][r0+width-1-k] == color:
                            score += 1
            if best is None or score > best[0]:
                best = (score, j)
        if best is not None:
            seams[color] = best[1]
    for color, j in seams.items():
        l0, l1 = col_spans[j]
        r0, r1 = col_spans[j+1]
        width = min(l1-l0, r1-r0)
        for y0, y1 in row_spans:
            for y in range(y0, y1):
                for k in range(width):
                    a, b = l0+k, r0+width-1-k
                    if grid[y][a] == color or grid[y][b] == color:
                        if out[y][a] == 0:
                            out[y][a] = color
                        if out[y][b] == 0:
                            out[y][b] = color
    return out
'''
